-- Базы-моки источников для кредитного конвейера. Сгенерировано: python -m alfa_ml.synth.
-- Не редактировать вручную: данные пересоздаются генератором с тем же seed.
\set ON_ERROR_STOP on
SELECT 'CREATE DATABASE mocks OWNER credit_kiosk'
WHERE NOT EXISTS (SELECT FROM pg_database WHERE datname = 'mocks')\gexec
ALTER DATABASE mocks OWNER TO credit_kiosk;
\connect mocks
SET ROLE credit_kiosk;
DROP TABLE IF EXISTS egr_roles CASCADE;
DROP TABLE IF EXISTS rfm_entries CASCADE;
DROP TABLE IF EXISTS fns_financials CASCADE;
DROP TABLE IF EXISTS fns_ens CASCADE;
DROP TABLE IF EXISTS egr_person_history CASCADE;
DROP TABLE IF EXISTS egr_organizations CASCADE;
DROP TABLE IF EXISTS efrsb_cases CASCADE;
DROP TABLE IF EXISTS bki_subjects CASCADE;
DROP TABLE IF EXISTS bki_loans CASCADE;
DROP TABLE IF EXISTS bki_inquiries CASCADE;
DROP TABLE IF EXISTS alfa_turnover CASCADE;
DROP TABLE IF EXISTS alfa_clients CASCADE;

CREATE TABLE alfa_clients (
	inn TEXT NOT NULL, 
	client_since DATE NOT NULL, 
	PRIMARY KEY (inn)
);
COMMENT ON TABLE alfa_clients IS 'Альфа: клиенты с расчётным счётом';

CREATE TABLE alfa_turnover (
	inn TEXT NOT NULL, 
	month DATE NOT NULL, 
	inflow_customers NUMERIC(15, 2) NOT NULL, 
	inflow_acquiring NUMERIC(15, 2) NOT NULL, 
	inflow_cash NUMERIC(15, 2) NOT NULL, 
	inflow_own_transfer NUMERIC(15, 2) NOT NULL, 
	inflow_loans NUMERIC(15, 2) NOT NULL, 
	inflow_owner_funding NUMERIC(15, 2) NOT NULL, 
	outflow_suppliers NUMERIC(15, 2) NOT NULL, 
	outflow_salary NUMERIC(15, 2) NOT NULL, 
	outflow_rent NUMERIC(15, 2) NOT NULL, 
	outflow_taxes NUMERIC(15, 2) NOT NULL, 
	outflow_other_debt NUMERIC(15, 2) NOT NULL, 
	outflow_own_transfer NUMERIC(15, 2) NOT NULL, 
	outflow_loan_payments NUMERIC(15, 2) NOT NULL, 
	outflow_owner_payouts NUMERIC(15, 2) NOT NULL, 
	top_customer_inflow NUMERIC(15, 2) NOT NULL, 
	PRIMARY KEY (inn, month)
);
COMMENT ON TABLE alfa_turnover IS 'Альфа: помесячные обороты по счёту, суммы по категориям операций';

CREATE TABLE bki_inquiries (
	inn TEXT NOT NULL, 
	inquiry_date DATE NOT NULL, 
	lender TEXT NOT NULL
);
CREATE INDEX bki_inquiries_inn ON bki_inquiries (inn);
COMMENT ON TABLE bki_inquiries IS 'БКИ: запросы кредитной истории другими кредиторами';

CREATE TABLE bki_loans (
	loan_id BIGINT NOT NULL, 
	borrower_inn TEXT NOT NULL, 
	lender TEXT NOT NULL, 
	is_business BOOLEAN NOT NULL, 
	balance NUMERIC(15, 2) NOT NULL, 
	monthly_payment NUMERIC(15, 2) NOT NULL, 
	remaining_months INTEGER NOT NULL, 
	PRIMARY KEY (loan_id)
);
CREATE INDEX bki_loans_borrower ON bki_loans (borrower_inn);
COMMENT ON TABLE bki_loans IS 'БКИ: действующие кредиты';

CREATE TABLE bki_subjects (
	inn TEXT NOT NULL, 
	subject_type TEXT NOT NULL, 
	has_history BOOLEAN NOT NULL, 
	max_dpd_24m INTEGER, 
	PRIMARY KEY (inn)
);
COMMENT ON TABLE bki_subjects IS 'БКИ: субъекты кредитных историй';

CREATE TABLE efrsb_cases (
	debtor_inn TEXT NOT NULL, 
	debtor_type TEXT NOT NULL, 
	status TEXT NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE
);
CREATE INDEX efrsb_cases_debtor ON efrsb_cases (debtor_inn);
COMMENT ON TABLE efrsb_cases IS 'ЕФРСБ: дела о банкротстве';

CREATE TABLE egr_organizations (
	inn TEXT NOT NULL, 
	ogrn TEXT NOT NULL, 
	legal_form TEXT NOT NULL CHECK (legal_form IN ('ip', 'ooo')), 
	name TEXT NOT NULL, 
	registration_date DATE NOT NULL, 
	status TEXT NOT NULL, 
	okved_code TEXT NOT NULL, 
	PRIMARY KEY (inn), 
	UNIQUE (ogrn)
);
COMMENT ON TABLE egr_organizations IS 'ЕГРЮЛ / ЕГРИП: организации и ИП';

CREATE TABLE egr_person_history (
	person_inn TEXT NOT NULL, 
	org_inn TEXT NOT NULL, 
	org_name TEXT NOT NULL, 
	role TEXT NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	outcome TEXT NOT NULL
);
CREATE INDEX egr_person_history_person ON egr_person_history (person_inn);
COMMENT ON TABLE egr_person_history IS 'Другие бизнесы человека, прошлые и действующие, и чем они закончились';

CREATE TABLE fns_ens (
	inn TEXT NOT NULL, 
	debt NUMERIC(15, 2) NOT NULL, 
	as_of_date DATE NOT NULL, 
	PRIMARY KEY (inn)
);
COMMENT ON TABLE fns_ens IS 'ФНС: сальдо единого налогового счёта';

CREATE TABLE fns_financials (
	inn TEXT NOT NULL, 
	year INTEGER NOT NULL, 
	revenue NUMERIC(15, 2) NOT NULL, 
	PRIMARY KEY (inn, year)
);
COMMENT ON TABLE fns_financials IS 'ФНС: доходы организаций за год из открытых данных; у ИП их нет';

CREATE TABLE rfm_entries (
	inn TEXT NOT NULL, 
	entity_type TEXT NOT NULL, 
	added_date DATE NOT NULL, 
	PRIMARY KEY (inn)
);
COMMENT ON TABLE rfm_entries IS 'Перечень Росфинмониторинга';

CREATE TABLE egr_roles (
	org_inn TEXT NOT NULL, 
	person_inn TEXT NOT NULL, 
	person_name TEXT NOT NULL, 
	is_director BOOLEAN NOT NULL, 
	share FLOAT(53) NOT NULL, 
	PRIMARY KEY (org_inn, person_inn), 
	FOREIGN KEY(org_inn) REFERENCES egr_organizations (inn)
);
COMMENT ON TABLE egr_roles IS 'Кто стоит за организацией: ИП, директор, участники с долями';












